def main():
    data = sys.stdin.buffer.read()
    try:
        obj = json.loads(data.decode("utf-8"))
    except Exception as exc:  # pragma: no cover - trusted, well formed input
        sys.stderr.write("input error: %r\n" % (exc,))
        os._exit(1)
    payload = json.dumps(process_batch(obj)).encode("utf-8") + b"\n"
    sys.stdout.buffer.write(payload)
    sys.stdout.buffer.flush()
    try:
        sys.stderr.flush()
    except Exception:
        pass
    os._exit(0)


if __name__ == "__main__":
    main()
